// Indie Flower as pen strokes, for notes that write themselves out (see
// HandNote). Generated by Tegaki's font generator, which the tegaki package
// doesn't ship a copy of for this font:
//   bun start generate "Indie Flower" -o <folder>   (github.com/gkurt/tegaki, packages/generator)
// Only the two font URLs differ from the generated file, so the bundler finds them.
import glyphData from './glyphData.json';

const fontUrl = new URL('./indie-flower-3dc76002.ttf', import.meta.url).href;
const fullFontUrl = new URL('./indie-flower.ttf', import.meta.url).href;

const bundle = {
  version: 1,
  family: 'Indie Flower Tegaki 3dc76002',
  fullFamily: 'Indie Flower',
  lineCap: 'round',
  fontUrl,
  fullFontUrl,
  fontFaceCSS: `@font-face { font-family: 'Indie Flower Tegaki 3dc76002'; src: url(${fontUrl}); } @font-face { font-family: 'Indie Flower'; src: url(${fullFontUrl}); }`,
  unitsPerEm: 1024,
  ascender: 994,
  descender: -500,
  glyphData,
} as const;

export default bundle;
